-- UTF-8. V361 prerequisite; additive address-code reference data and nullable snapshot.
-- Scope: new System reference rows only, no current area changes, no role grants or business-row updates.
-- Repeatable: fixed IDs and data version; conflicting existing rows abort. DDL may commit partially.
-- Recovery: rerun after correcting failure; rollback application first, retain added data/column.
SET NAMES utf8mb4;
DROP PROCEDURE IF EXISTS zsjos_v362_apply;
DELIMITER $$
CREATE PROCEDURE zsjos_v362_apply()
BEGIN
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 IF NOT EXISTS(SELECT 1 FROM zsjos_schema_version WHERE version='V361')
 OR NOT EXISTS(SELECT 1 FROM zsjos_module_schema_version WHERE module_code='core' AND version='V361') THEN
 SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V362 requires V361 in both ledgers'; END IF;
CREATE TABLE IF NOT EXISTS system_identity_area (
 id BIGINT NOT NULL PRIMARY KEY,
 code VARCHAR(6) NOT NULL,
 province_name VARCHAR(100) NOT NULL,
 city_name VARCHAR(100) NOT NULL,
 name VARCHAR(100) NOT NULL,
 record_status VARCHAR(20) NOT NULL,
 valid_from VARCHAR(20) NOT NULL,
 valid_until VARCHAR(20) NOT NULL,
 successor_codes TEXT NOT NULL,
 data_version VARCHAR(64) NOT NULL,
 KEY idx_identity_area_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='zsjos_student_info_form_value' AND column_name='identity_area_snapshot') THEN
 ALTER TABLE zsjos_student_info_form_value ADD COLUMN identity_area_snapshot TEXT NULL COMMENT '身份证地址码识别来源快照';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='zsjos_student_info_form_value' AND column_name='identity_area_snapshot' AND data_type='text' AND is_nullable='YES') THEN
 SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V362 snapshot column mismatch'; END IF;
 START TRANSACTION;
